<?php
namespace App\Services; use App\Enums\OrderStatus; use App\Models\{Address,Cart,Order,Payment}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class OrderService { public function checkout(Cart $cart,Address $address):array {return DB::transaction(function()use($cart,$address){$cart->load('items.product.vendor','coupon');$totals=app(CartService::class)->totals($cart);$orders=[];foreach($cart->items->groupBy(fn($i)=>$i->product->vendor_id) as $vendorId=>$items){$subtotal=(float)$items->sum(fn($i)=>(float)$i->unit_price*$i->quantity);$share=$subtotal/max($totals['subtotal'],.01);$order=Order::create(['number'=>'TM-'.strtoupper(Str::random(10)),'customer_id'=>$cart->user_id,'vendor_id'=>$vendorId,'shipping_address'=>$address->toArray(),'status'=>OrderStatus::Pending,'subtotal'=>$subtotal,'discount_total'=>$totals['discount']*$share,'tax_total'=>$totals['tax']*$share,'shipping_total'=>$totals['shipping']*$share,'grand_total'=>$totals['total']*$share,'placed_at'=>now()]);foreach($items as $item){$order->items()->create(['product_id'=>$item->product_id,'product_name'=>$item->product->name,'sku'=>$item->product->sku,'variant'=>$item->variant,'quantity'=>$item->quantity,'unit_price'=>$item->unit_price,'total'=>$item->unit_price*$item->quantity]);$item->product->inventory()->decrement('quantity',$item->quantity);}$order->payment()->create(['gateway'=>'payfast','amount'=>$order->grand_total,'status'=>'pending']);$orders[]=$order;} $cart->items()->delete();$cart->update(['coupon_id'=>null]);return $orders;});} }
